mapper.select:
SELECT * FROM wechatwork_moment_interactions

    moment_id = #{momentId}
    AND external_userid = #{externalUserid}
    AND interaction_type = #{interactionType}
    AND deleted = 0

SELECT COUNT(*) FROM wechatwork_moment_interactions

    wechatwork_users_id = #{wechatworkUsersId}
    AND interaction_type = 1
    AND deleted = 0

        AND interaction_time >= #{startTime}


        AND interaction_time <= #{endTime}

SELECT COUNT(*) FROM wechatwork_moment_interactions

    wechatwork_users_id = #{wechatworkUsersId}
    AND interaction_type = 2
    AND deleted = 0

        AND interaction_time >= #{startTime}


        AND interaction_time <= #{endTime}

SELECT external_userid, COUNT(*) as interaction_count
FROM wechatwork_moment_interactions

    wechatwork_users_id = #{wechatworkUsersId}
    AND deleted = 0

        AND interaction_time >= #{startTime}


        AND interaction_time <= #{endTime}


GROUP BY external_userid
ORDER BY interaction_count DESC
LIMIT #{limit}
